/**
 * `@/lib/app-auth` for the e2e bundle ONLY (tsconfig `paths`, generated by pose-run.mjs).
 *
 * The real module resolves a Supabase JWT and mirrors the member into `accounts` +
 * `user_profiles`. Reproducing that would mean either shipping a fake token verifier into a test —
 * which is exactly the kind of thing that later gets copied — or holding a real Supabase session,
 * which the sandbox has no business doing.
 *
 * So the stub swaps ONE thing: how a bearer string becomes an email. Everything the route does
 * AFTER `getMember()` returns is the shipped code, and the returned `id` is read from the local
 * database, so foreign keys, uniqueness and the `account_id` the audit rows carry are all real.
 *
 * Two properties keep the stub honest:
 *   - it only answers for addresses in `E2E_MEMBERS`, which the runner sets from the suite's own
 *     fixture list. An arbitrary email in a header therefore cannot drive the route at all, so a
 *     passing "unauthenticated requests are refused" test still means something;
 *   - it returns `null` exactly when the real module would: no/unknown bearer, or an email with no
 *     member row. The route's 401 path is exercised, not imitated.
 */
import { and, eq } from "drizzle-orm";
import { db } from "@/db";
import { accounts, userProfiles } from "@/db/schema";

export type Member = { id: string; email: string; name: string };

const ALLOWED = new Set(
  (process.env.E2E_MEMBERS ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean)
);

/* The suite mints fixture members as it needs them (`e2e-<mode>-<n>@freeborn.test`), so the
   allow-list also accepts that SHAPE. It is a shape test, not a wildcard: an address outside the
   reserved fixture domain — including any real member address, and anything@freeborn.test that is
   not `e2e-<letters>-<digits>` — is still refused, which keeps the "unauthenticated requests are
   rejected" assertion meaningful rather than vacuous. */
const FIXTURE_SHAPE = /^e2e-[a-z]+-\d+@freeborn\.test$/;

function bearerEmail(request: Request): string | null {
  const h = request.headers.get("authorization") ?? "";
  const m = /^Bearer e2e:([^\s]+)$/.exec(h.trim());
  if (!m) return null;
  const email = m[1]!.toLowerCase();
  return ALLOWED.has(email) || FIXTURE_SHAPE.test(email) ? email : null;
}

export async function getMember(request: Request): Promise<Member | null> {
  const email = bearerEmail(request);
  if (!email) return null;
  const [row] = await db
    .select({ id: userProfiles.id, email: userProfiles.email, name: userProfiles.displayName })
    .from(userProfiles)
    .where(and(eq(userProfiles.email, email)))
    .limit(1);
  if (!row) return null;
  /* The real module guarantees the accounts mirror exists; the route's FK to accounts.id depends
     on it, so the stub keeps that promise rather than letting the suite pass by accident. */
  await db
    .insert(accounts)
    .values({ id: row.id, email })
    .onConflictDoNothing({ target: accounts.id });
  return { id: row.id, email, name: row.name ?? email.split("@")[0]! };
}

export async function getLocalProfile(profileId: string) {
  const [row] = await db.select().from(userProfiles).where(eq(userProfiles.id, profileId)).limit(1);
  return row ?? null;
}
